<?php
require_once __DIR__.'/../../includes/staff/operations.php';require_login();verify_csrf();$pdo=staff_db();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['lead_id'];$stage=$_POST['stage']??'new';$pdo->prepare('UPDATE leads SET stage=? WHERE id=?')->execute([$stage,$id]);flash('success','Lead stage updated.');staff_redirect('staff/pages/leads.php');}
$rows=$pdo->query("SELECT l.*,c.name customer_name,c.customer_code,c.phone,c.interested_service,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) assigned_name FROM leads l JOIN customers c ON c.id=l.customer_id LEFT JOIN staff s ON s.id=l.assigned_to ORDER BY l.updated_at DESC")->fetchAll();$groups=[];foreach(lead_stages() as $k=>$v)$groups[$k]=[];foreach($rows as $r)$groups[$r['stage']][]=$r;$pageTitle='Sales Pipeline';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">CRM</p><h1>Sales pipeline</h1><p class="muted">Move every enquiry from first contact through consultation, quotation and close.</p></div><a class="btn primary" href="<?= h(ideare_root_url('staff/pages/customers.php')) ?>">Add customer</a></div><div class="crm-grid"><?php foreach(lead_stages() as $stage=>$label):?><section class="pipeline-column"><h3><?= h($label) ?> · <?= count($groups[$stage]) ?></h3><?php foreach($groups[$stage] as $r):?><article class="pipeline-card"><a href="<?= h(ideare_root_url('staff/pages/customer-view.php?id='.$r['customer_id'])) ?>" style="color:inherit;text-decoration:none"><b><?= h($r['customer_name']) ?></b><small><?= h($r['interested_service']?:'Unspecified service') ?></small><small><?= money($r['estimated_value']) ?> · <?= h($r['assigned_name']?:'Unassigned') ?></small><?php if($r['next_follow_up_at']):?><small>Follow-up: <?= h(date('j M, g:i A',strtotime($r['next_follow_up_at']))) ?></small><?php endif;?></a><form method="post" style="margin-top:8px"><?= csrf_field() ?><input type="hidden" name="lead_id" value="<?= $r['id'] ?>"><select name="stage" onchange="this.form.submit()" aria-label="Change stage"><?php foreach(lead_stages() as $k=>$v):?><option value="<?= $k ?>" <?= $r['stage']===$k?'selected':'' ?>><?= h($v) ?></option><?php endforeach;?></select></form></article><?php endforeach;?><?php if(!$groups[$stage]):?><p class="muted tiny">No leads.</p><?php endif;?></section><?php endforeach;?></div></main>
<?php require __DIR__.'/../../includes/staff/footer.php'; ?>
